// LinkCheck runner (F1.10). Spawns the harness in a NEW Node process under the permission model.
// The harness is our own code and is not generated by a model; --allow-inspector is required only
// to read coverage from memory. There is no --allow-fs-write and no --allow-net, so neither the
// test nor the analyzed repository modules can write or reach the network here.
//
// Node 22 does not support --allow-inspector: the spawn fails and LinkCheck is `unproven`
// (fail-closed). Only Node 26 can award execution-proven and patch-proven.
import { execFile } from "node:child_process";
import { rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

export const LINKCHECK_HARNESS = fileURLToPath(new URL("./linkcheck-harness.mjs", import.meta.url));

function spawnNode(args, timeoutMs) {
  return new Promise(function (resolve) {
    execFile(process.execPath, args, { timeout: timeoutMs, maxBuffer: 1024 * 1024, env: { PATH: process.env.PATH || "" } }, function (error, stdout, stderr) {
      resolve({
        exitCode: error ? (typeof error.code === "number" ? error.code : null) : 0,
        stdout: String(stdout || ""),
        stderr: String(stderr || ""),
        error: error ? error.message : null
      });
    });
  });
}

function stripDotSlash(specifier) {
  return specifier.replace(/^\.\//, "");
}

export async function runLinkCheck(options) {
  const testCode = options.testCode;
  const snapshotDir = options.snapshotDir;
  const targetFile = stripDotSlash(options.targetFile || "");
  const symbols = Array.isArray(options.symbols) ? options.symbols : [];
  const timeoutMs = options.timeoutMs || 8000;
  const result = { status: "unproven", targetFile: targetFile, symbols: symbols, executed: {}, detail: null };
  if (!testCode || !snapshotDir || !targetFile || symbols.length === 0) {
    result.detail = "linkcheck needs testCode, snapshotDir, targetFile and at least one symbol";
    return result;
  }
  const probePath = join(snapshotDir, ".codeproof-linkcheck.probe.mjs");
  try {
    writeFileSync(probePath, testCode);
    const args = [
      "--permission",
      "--allow-inspector",
      "--allow-fs-read=" + snapshotDir,
      "--allow-fs-read=" + LINKCHECK_HARNESS,
      LINKCHECK_HARNESS,
      probePath,
      targetFile
    ].concat(symbols);
    const run = await spawnNode(args, timeoutMs);
    const combined = run.stderr + "\n" + run.stdout;
    if (/bad option|unknown option|--allow-inspector/i.test(run.stderr) && !/\{"status"/.test(run.stdout)) {
      result.detail = "inspector coverage is not available on this Node runtime (Node 22 has no --allow-inspector); link-unproven";
      return result;
    }
    if (/ERR_ACCESS_DENIED|PermissionDenied/i.test(combined) && !/\{"status"/.test(run.stdout)) {
      result.detail = "the permission model denied the linkcheck run; link-unproven";
      return result;
    }
    const line = run.stdout.trim().split("\n").filter(function (item) { return item.trim().startsWith("{"); }).pop();
    if (!line) {
      result.detail = "linkcheck harness produced no result" + (run.stderr ? ": " + run.stderr.trim().split("\n").slice(-1)[0] : "");
      return result;
    }
    const parsed = JSON.parse(line);
    result.status = parsed.status === "proven" ? "proven" : parsed.status === "error" ? "error" : "unproven";
    result.executed = parsed.executed || {};
    result.detail = parsed.status === "unproven" ? "the imported symbol never executed (dead or decorative call)" : (parsed.error || null);
    return result;
  } catch (error) {
    result.status = "error";
    result.detail = error.message;
    return result;
  } finally {
    try { rmSync(probePath, { force: true }); } catch (error) { /* probe cleanup is best effort */ }
  }
}